package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type PropDef struct {
	Type    string `json:"type"`
	Default any    `json:"default"`
	Summary string `json:"summary"`
}

type SizeSpecDef struct {
	W int `json:"w"`
	H int `json:"h"`
}

type SizePolicyDef struct {
	H string `json:"h"`
	V string `json:"v"`
}

type WidgetDef struct {
	Extends     string             `json:"extends"`
	Summary     string             `json:"summary"`
	Properties  map[string]PropDef `json:"properties"`
	Signals     []string           `json:"signals"`
	Localizable []string           `json:"localizable"`
	SizeHint    *SizeSpecDef       `json:"sizeHint"`
	MinSize     *SizeSpecDef       `json:"minSize"`
	SizePolicy  *SizePolicyDef     `json:"sizePolicy"`
}

type LayoutDef struct {
	Summary    string             `json:"summary"`
	Properties map[string]PropDef `json:"properties"`
}

type Vocabulary struct {
	Version      int                  `json:"version"`
	Widgets      map[string]WidgetDef `json:"widgets"`
	Layouts      map[string]LayoutDef `json:"layouts"`
	Commands     map[string]int       `json:"commands"`
	PaletteRoles []string             `json:"paletteRoles"`
}

func LoadVocabulary(path string) (*Vocabulary, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var v Vocabulary
	if err := json.Unmarshal(data, &v); err != nil {
		return nil, err
	}
	return &v, nil
}

func GenerateWidgetsMarkdown(v *Vocabulary) string {
	var b strings.Builder
	b.WriteString("# Справочник виджетов и свойств vtui\n\n")
	b.WriteString("Этот файл сгенерирован автоматически из `vocabulary.json` с помощью `cmd/vtui-gen`. **Не редактируйте вручную.**\n\n")

	b.WriteString("## Виджеты\n\n")

	names := make([]string, 0, len(v.Widgets))
	for name := range v.Widgets {
		names = append(names, name)
	}
	sort.Strings(names)

	for _, name := range names {
		w := v.Widgets[name]
		fmt.Fprintf(&b, "### `%s`\n\n", name)
		fmt.Fprintf(&b, "%s\n\n", w.Summary)

		if w.Extends != "" {
			fmt.Fprintf(&b, "*Наследует:* `%s`\n\n", w.Extends)
		}

		if w.SizeHint != nil || w.MinSize != nil || w.SizePolicy != nil {
			b.WriteString("**Геометрия по умолчанию:**\n")
			if w.SizeHint != nil {
				fmt.Fprintf(&b, "- `sizeHint`: %d × %d ячеек\n", w.SizeHint.W, w.SizeHint.H)
			}
			if w.MinSize != nil {
				fmt.Fprintf(&b, "- `minSize`: %d × %d ячеек\n", w.MinSize.W, w.MinSize.H)
			}
			if w.SizePolicy != nil {
				fmt.Fprintf(&b, "- `sizePolicy`: h=`%s`, v=`%s`\n", w.SizePolicy.H, w.SizePolicy.V)
			}
			b.WriteString("\n")
		}

		if len(w.Properties) > 0 {
			b.WriteString("**Свойства:**\n\n")
			b.WriteString("| Свойство | Тип | По умолчанию | Описание |\n")
			b.WriteString("|---|---|---|---|\n")

			pNames := make([]string, 0, len(w.Properties))
			for pn := range w.Properties {
				pNames = append(pNames, pn)
			}
			sort.Strings(pNames)

			for _, pn := range pNames {
				prop := w.Properties[pn]
				defStr := fmt.Sprintf("%v", prop.Default)
				if prop.Type == "string" {
					defStr = fmt.Sprintf("%q", prop.Default)
				}
				fmt.Fprintf(&b, "| `%s` | `%s` | `%s` | %s |\n", pn, prop.Type, defStr, prop.Summary)
			}
			b.WriteString("\n")
		}

		if len(w.Signals) > 0 {
			b.WriteString("**Сигналы:** ")
			sigList := make([]string, len(w.Signals))
			for i, s := range w.Signals {
				sigList[i] = fmt.Sprintf("`%s`", s)
			}
			b.WriteString(strings.Join(sigList, ", "))
			b.WriteString("\n\n")
		}

		if len(w.Localizable) > 0 {
			b.WriteString("**Локализуемые свойства:** ")
			locList := make([]string, len(w.Localizable))
			for i, l := range w.Localizable {
				locList[i] = fmt.Sprintf("`%s`", l)
			}
			b.WriteString(strings.Join(locList, ", "))
			b.WriteString("\n\n")
		}

		b.WriteString("---\n\n")
	}

	b.WriteString("## Контейнеры раскладки\n\n")
	lNames := make([]string, 0, len(v.Layouts))
	for name := range v.Layouts {
		lNames = append(lNames, name)
	}
	sort.Strings(lNames)

	for _, name := range lNames {
		l := v.Layouts[name]
		fmt.Fprintf(&b, "### `%s`\n\n", name)
		fmt.Fprintf(&b, "%s\n\n", l.Summary)
		if len(l.Properties) > 0 {
			b.WriteString("| Свойство | Тип | По умолчанию | Описание |\n")
			b.WriteString("|---|---|---|---|\n")
			lpNames := make([]string, 0, len(l.Properties))
			for lpn := range l.Properties {
				lpNames = append(lpNames, lpn)
			}
			sort.Strings(lpNames)
			for _, lpn := range lpNames {
				prop := l.Properties[lpn]
				defStr := fmt.Sprintf("%v", prop.Default)
				fmt.Fprintf(&b, "| `%s` | `%s` | `%s` | %s |\n", lpn, prop.Type, defStr, prop.Summary)
			}
			b.WriteString("\n")
		}
	}

	return b.String()
}

func GeneratePropertiesGo(v *Vocabulary) string {
	var b strings.Builder
	b.WriteString("// Code generated by vtui-gen. DO NOT EDIT.\n\n")
	b.WriteString("package vtui\n\n")
	b.WriteString("import (\n\t\"fmt\"\n)\n\n")

	names := make([]string, 0, len(v.Widgets))
	for name := range v.Widgets {
		if name == "Widget" || name == "Dialog" || name == "Label" || name == "Spacer" || name == "Desktop" || name == "StatusLine" || name == "MenuBar" || name == "KeyBar" {
			continue
		}
		names = append(names, name)
	}
	sort.Strings(names)

	for _, name := range names {
		w := v.Widgets[name]
		if len(w.Properties) == 0 {
			continue
		}

		pNames := make([]string, 0, len(w.Properties))
		for pn := range w.Properties {
			pNames = append(pNames, pn)
		}
		sort.Strings(pNames)

		// SetProperty method
		fmt.Fprintf(&b, "// SetProperty sets a property value on %s.\n", name)
		fmt.Fprintf(&b, "func (o *%s) SetProperty(name string, v PropValue) error {\n", name)
		b.WriteString("\tswitch name {\n")
		for _, pn := range pNames {
			prop := w.Properties[pn]
			fmt.Fprintf(&b, "\tcase %q:\n", pn)
			kindCheck := propKindCheck(prop.Type)
			fmt.Fprintf(&b, "\t\tif v.Kind != %s {\n\t\t\treturn ErrPropertyType\n\t\t}\n", kindCheck)
			setter := generateSetterCode(name, pn, prop)
			b.WriteString(setter)
			b.WriteString("\t\treturn nil\n")
		}
		b.WriteString("\tdefault:\n")
		if w.Extends != "" && w.Extends != "Widget" {
			fmt.Fprintf(&b, "\t\treturn o.%s.SetProperty(name, v)\n", w.Extends)
		} else {
			b.WriteString("\t\treturn o.ScreenObject.SetProperty(name, v)\n")
		}
		b.WriteString("\t}\n}\n\n")

		// GetProperty method
		fmt.Fprintf(&b, "// GetProperty retrieves a property value from %s.\n", name)
		fmt.Fprintf(&b, "func (o *%s) GetProperty(name string) (PropValue, bool) {\n", name)
		b.WriteString("\tswitch name {\n")
		for _, pn := range pNames {
			getter := generateGetterCode(name, pn, w.Properties[pn])
			fmt.Fprintf(&b, "\tcase %q:\n\t\treturn %s, true\n", pn, getter)
		}
		b.WriteString("\tdefault:\n")
		if w.Extends != "" && w.Extends != "Widget" {
			fmt.Fprintf(&b, "\t\treturn o.%s.GetProperty(name)\n", w.Extends)
		} else {
			b.WriteString("\t\treturn o.ScreenObject.GetProperty(name)\n")
		}
		b.WriteString("\t}\n}\n\n")
	}

	return b.String()
}

func propKindCheck(typ string) string {
	switch typ {
	case "string":
		return "PropString"
	case "int":
		return "PropInt"
	case "bool":
		return "PropBool"
	case "color":
		return "PropColor"
	case "stringList":
		return "PropStringList"
	case "rect":
		return "PropRect"
	default:
		return "PropString"
	}
}

func generateSetterCode(widget, propName string, prop PropDef) string {
	switch widget {
	case "Button":
		switch propName {
		case "text":
			return "\t\to.SetText(v.S)\n"
		case "default":
			return "\t\to.IsDefault = v.B\n"
		case "command":
			return "\t\to.Command = v.I\n"
		}
	case "Checkbox":
		switch propName {
		case "text":
			return "\t\to.SetText(v.S)\n"
		case "state":
			return "\t\to.State = v.I\n\t\to.NotifyChange()\n"
		case "threeState":
			return "\t\to.ThreeState = v.B\n"
		}
	case "RadioButton":
		switch propName {
		case "text":
			return "\t\to.SetText(v.S)\n"
		case "selected":
			return "\t\to.Selected = v.B\n\t\to.NotifyChange()\n"
		}
	case "RadioGroup":
		switch propName {
		case "items":
			return "\t\to.Items = v.L\n\t\to.colWidths = calcGridColWidths(o.Columns, o.Items)\n"
		case "selected":
			return "\t\to.SetData(v.I)\n"
		case "columns":
			return "\t\to.Columns = v.I\n\t\to.colWidths = calcGridColWidths(o.Columns, o.Items)\n"
		}
	case "CheckGroup":
		switch propName {
		case "items":
			return "\t\to.Items = v.L\n\t\to.States = make([]bool, len(v.L))\n\t\to.colWidths = calcGridColWidths(o.Columns, o.Items)\n"
		case "data":
			return "\t\to.SetData(uint32(v.I))\n"
		case "columns":
			return "\t\to.Columns = v.I\n\t\to.colWidths = calcGridColWidths(o.Columns, o.Items)\n"
		}
	case "Edit":
		switch propName {
		case "text":
			return "\t\to.SetText(v.S)\n"
		case "password":
			return "\t\to.PasswordMode = v.B\n"
		case "historyId":
			return "\t\to.HistoryID = v.S\n"
		case "showHistoryButton":
			return "\t\to.ShowHistoryButton = v.B\n"
		}
	case "MultiLineEdit":
		switch propName {
		case "text":
			return "\t\to.SetText(v.S)\n"
		}
	case "Label":
		switch propName {
		case "text":
			return "\t\to.SetText(v.S)\n"
		case "buddy":
			return "\t\t_ = v.S\n"
		}
	case "Text":
		switch propName {
		case "text":
			return "\t\to.SetText(v.S)\n"
		}
	case "ListBox":
		switch propName {
		case "items":
			return "\t\to.Items = v.L\n\t\to.UpdateRows()\n"
		case "selected":
			return "\t\to.SetSelectPos(v.I)\n"
		case "multiSelect":
			return "\t\to.MultiSelect = v.B\n"
		}
	case "ComboBox":
		switch propName {
		case "text":
			return "\t\to.Edit.SetText(v.S)\n"
		case "items":
			return "\t\to.Menu.Items = nil\n\t\tfor _, it := range v.L {\n\t\t\to.Menu.AddItem(MenuItem{Text: it})\n\t\t}\n"
		case "dropdownOnly":
			return "\t\to.DropdownOnly = v.B\n"
		}
	case "Table":
		switch propName {
		case "showHeader":
			return "\t\to.ShowHeader = v.B\n"
		case "showSeparators":
			return "\t\to.ShowSeparators = v.B\n"
		case "sortable":
			return "\t\to.Sortable = v.B\n"
		case "quickSearch":
			return "\t\to.QuickSearch = v.B\n"
		case "selected":
			return "\t\to.SetSelectPos(v.I)\n"
		}
	case "VMenu":
		switch propName {
		case "title":
			return "\t\to.title = v.S\n"
		case "selected":
			return "\t\to.SetSelectPos(v.I)\n"
		}
	case "Dialog", "Window":
		switch propName {
		case "title":
			return "\t\to.SetTitle(v.S)\n"
		case "showClose":
			return "\t\to.ShowClose = v.B\n"
		case "showZoom":
			return "\t\to.ShowZoom = v.B\n"
		case "isWarning":
			return "\t\to.IsWarning = v.B\n"
		case "autoSize":
			return "\t\t_ = v.B\n"
		case "center":
			return "\t\t_ = v.B\n"
		}
	case "BorderedFrame":
		switch propName {
		case "title":
			return "\t\to.SetTitle(v.S)\n"
		case "boxType":
			return "\t\to.boxType = v.I\n"
		case "showClose":
			return "\t\to.ShowClose = v.B\n"
		}
	case "GroupBox":
		switch propName {
		case "title":
			return "\t\to.SetText(v.S)\n"
		}
	case "ProgressBar":
		switch propName {
		case "percent":
			return "\t\to.SetPercent(v.I)\n"
		}
	case "Separator":
		switch propName {
		case "connectLeft":
			return "\t\to.ConnectLeft = v.B\n"
		case "connectRight":
			return "\t\to.ConnectRight = v.B\n"
		}
	}
	return "\t\t_ = v\n"
}

func generateGetterCode(widget, propName string, prop PropDef) string {
	switch widget {
	case "Button":
		switch propName {
		case "text":
			return "PropValString(o.GetCaption())"
		case "default":
			return "PropValBool(o.IsDefault)"
		case "command":
			return "PropValInt(o.Command)"
		}
	case "Checkbox":
		switch propName {
		case "text":
			return "PropValString(o.cleanText)"
		case "state":
			return "PropValInt(o.State)"
		case "threeState":
			return "PropValBool(o.ThreeState)"
		}
	case "RadioButton":
		switch propName {
		case "text":
			return "PropValString(o.cleanText)"
		case "selected":
			return "PropValBool(o.Selected)"
		}
	case "RadioGroup":
		switch propName {
		case "items":
			return "PropValStringList(o.Items)"
		case "selected":
			return "PropValInt(o.Selected)"
		case "columns":
			return "PropValInt(o.Columns)"
		}
	case "CheckGroup":
		switch propName {
		case "items":
			return "PropValStringList(o.Items)"
		case "data":
			return "PropValInt(int(o.GetData().(uint32)))"
		case "columns":
			return "PropValInt(o.Columns)"
		}
	case "Edit":
		switch propName {
		case "text":
			return "PropValString(o.GetText())"
		case "password":
			return "PropValBool(o.PasswordMode)"
		case "historyId":
			return "PropValString(o.HistoryID)"
		case "showHistoryButton":
			return "PropValBool(o.ShowHistoryButton)"
		}
	case "MultiLineEdit":
		switch propName {
		case "text":
			return "PropValString(o.GetText())"
		}
	case "Label":
		switch propName {
		case "text":
			return "PropValString(o.cleanText)"
		case "buddy":
			return "PropValString(\"\")"
		}
	case "Text":
		switch propName {
		case "text":
			return "PropValString(o.cleanText)"
		}
	case "ListBox":
		switch propName {
		case "items":
			return "PropValStringList(o.Items)"
		case "selected":
			return "PropValInt(o.SelectPos)"
		case "multiSelect":
			return "PropValBool(o.MultiSelect)"
		}
	case "ComboBox":
		switch propName {
		case "text":
			return "PropValString(o.Edit.GetText())"
		case "items":
			return "PropValStringList(func() []string { var res []string; for _, it := range o.Menu.Items { res = append(res, it.Text) }; return res }())"
		case "dropdownOnly":
			return "PropValBool(o.DropdownOnly)"
		}
	case "Table":
		switch propName {
		case "showHeader":
			return "PropValBool(o.ShowHeader)"
		case "showSeparators":
			return "PropValBool(o.ShowSeparators)"
		case "sortable":
			return "PropValBool(o.Sortable)"
		case "quickSearch":
			return "PropValBool(o.QuickSearch)"
		case "selected":
			return "PropValInt(o.SelectPos)"
		}
	case "VMenu":
		switch propName {
		case "title":
			return "PropValString(o.title)"
		case "selected":
			return "PropValInt(o.SelectPos)"
		}
	case "Dialog", "Window":
		switch propName {
		case "title":
			return "PropValString(o.GetTitle())"
		case "showClose":
			return "PropValBool(o.ShowClose)"
		case "showZoom":
			return "PropValBool(o.ShowZoom)"
		case "isWarning":
			return "PropValBool(o.IsWarning)"
		case "autoSize":
			return "PropValBool(false)"
		case "center":
			return "PropValBool(true)"
		}
	case "BorderedFrame":
		switch propName {
		case "title":
			return "PropValString(o.GetTitle())"
		case "boxType":
			return "PropValInt(o.boxType)"
		case "showClose":
			return "PropValBool(o.ShowClose)"
		}
	case "GroupBox":
		switch propName {
		case "title":
			return "PropValString(o.cleanText)"
		}
	case "ProgressBar":
		switch propName {
		case "percent":
			return "PropValInt(o.Percent)"
		}
	case "Separator":
		switch propName {
		case "connectLeft":
			return "PropValBool(o.ConnectLeft)"
		case "connectRight":
			return "PropValBool(o.ConnectRight)"
		}
	}
	return "PropValString(\"\")"
}

func main() {
	vocabPath := "vocabulary.json"
	if len(os.Args) > 1 {
		vocabPath = os.Args[1]
	}

	v, err := LoadVocabulary(vocabPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error loading vocabulary: %v\n", err)
		os.Exit(1)
	}

	doc := GenerateWidgetsMarkdown(v)
	docsDir := "docs"
	if err := os.MkdirAll(docsDir, 0755); err != nil {
		fmt.Fprintf(os.Stderr, "Error creating docs dir: %v\n", err)
		os.Exit(1)
	}

	outPath := filepath.Join(docsDir, "widgets.md")
	if err := os.WriteFile(outPath, []byte(doc), 0644); err != nil {
		fmt.Fprintf(os.Stderr, "Error writing %s: %v\n", outPath, err)
		os.Exit(1)
	}

	propCode := GeneratePropertiesGo(v)
	propOutPath := "properties_gen.go"
	if err := os.WriteFile(propOutPath, []byte(propCode), 0644); err != nil {
		fmt.Fprintf(os.Stderr, "Error writing %s: %v\n", propOutPath, err)
		os.Exit(1)
	}

	pyDir := filepath.Join("bindings", "python", "vtui")
	if err := os.MkdirAll(pyDir, 0755); err == nil {
		pyProps := GeneratePythonProps(v)
		pyPath := filepath.Join(pyDir, "_props.py")
		_ = os.WriteFile(pyPath, []byte(pyProps), 0644)
	}

	nodeDir := filepath.Join("bindings", "node")
	if err := os.MkdirAll(nodeDir, 0755); err == nil {
		tsDefs := GenerateTypeScriptDefinitions(v)
		tsPath := filepath.Join(nodeDir, "vtui.d.ts")
		_ = os.WriteFile(tsPath, []byte(tsDefs), 0644)
	}

	cDir := filepath.Join("bindings", "c", "include")
	if err := os.MkdirAll(cDir, 0755); err == nil {
		cConsts := GenerateCConstants(v)
		cPath := filepath.Join(cDir, "vtui_constants.h")
		_ = os.WriteFile(cPath, []byte(cConsts), 0644)
	}

	fmt.Printf("Generated %s and %s successfully.\n", outPath, propOutPath)
}
func GenerateCConstants(v *Vocabulary) string {
	var b strings.Builder
	b.WriteString("/* Code generated by vtui-gen. DO NOT EDIT. */\n\n")
	b.WriteString("#ifndef VTUI_CONSTANTS_H\n#define VTUI_CONSTANTS_H\n\n")

	b.WriteString("/* Commands */\n")
	cmdNames := make([]string, 0, len(v.Commands))
	for name := range v.Commands {
		cmdNames = append(cmdNames, name)
	}
	sort.Strings(cmdNames)

	for _, name := range cmdNames {
		val := v.Commands[name]
		cName := "VTUI_" + strings.ToUpper(name)
		fmt.Fprintf(&b, "#define %-24s %d\n", cName, val)
	}

	b.WriteString("\n#endif /* VTUI_CONSTANTS_H */\n")
	return b.String()
}
func GenerateTypeScriptDefinitions(v *Vocabulary) string {
	var b strings.Builder
	b.WriteString("// Code generated by vtui-gen. DO NOT EDIT.\n\n")

	b.WriteString("export interface RunOptions {\n")
	b.WriteString("  hostBin?: string;\n")
	b.WriteString("  backend?: 'ansi' | 'gogpu' | 'x11' | 'wayland' | 'ebiten';\n")
	b.WriteString("}\n\n")

	b.WriteString("export class VtuiError extends Error {\n")
	b.WriteString("  code: string;\n")
	b.WriteString("  replyTo?: number;\n")
	b.WriteString("  constructor(code: string, message: string, replyTo?: number);\n")
	b.WriteString("}\n\n")

	b.WriteString("export interface Ui {\n")
	b.WriteString("  dialog(title: string, w?: number, callback?: () => void): any;\n")
	b.WriteString("  edit(label: string, defaultValue?: string, id?: string): string;\n")
	b.WriteString("  button(text: string, id?: string): boolean;\n")
	b.WriteString("  checkbox(text: string, defaultValue?: boolean, id?: string): boolean;\n")
	b.WriteString("  message(title: string, text: string, buttons?: string[]): void;\n")
	b.WriteString("}\n\n")

	b.WriteString("export function run(uiFunc: (u: Ui) => void, options?: RunOptions): void;\n")
	b.WriteString("export function log(...args: any[]): void;\n")
	return b.String()
}
func GeneratePythonProps(v *Vocabulary) string {
	var b strings.Builder
	b.WriteString("# Code generated by vtui-gen. DO NOT EDIT.\n\n")
	b.WriteString("import json\n\n")

	data, _ := json.Marshal(v)
	b.WriteString("VOCABULARY = json.loads(")
	fmt.Fprintf(&b, "%q", string(data))
	b.WriteString(")\n\n")

	b.WriteString("COMMANDS = VOCABULARY.get('commands', {})\n")
	b.WriteString("PALETTE_ROLES = VOCABULARY.get('paletteRoles', [])\n")
	b.WriteString("WIDGETS = VOCABULARY.get('widgets', {})\n")
	return b.String()
}
